import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Ticket","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/ticket.md","filePath":"03-developer/models/ticket.md"}`),a={name:`03-developer/models/ticket.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="ticket" tabindex="-1">Ticket <a class="header-anchor" href="#ticket" aria-label="Permalink to “Ticket”">​</a></h1><p>The <code>Ticket</code> model is used to manage customer support tickets. Each ticket can include a customer message, an administrator response, a handling status, and child tickets. Tickets can also be evaluated and rated.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique ticket ID</td></tr><tr><td><code>title</code></td><td>VARCHAR(128)</td><td>Yes</td><td>Ticket title; used for parent tickets without a category</td></tr><tr><td><code>customer_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the customer who submitted the ticket</td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the user or administrator who submitted the response</td></tr><tr><td><code>body</code></td><td>TEXT</td><td>No</td><td>Ticket message text; not translated</td></tr><tr><td><code>status</code></td><td>ENUM(&#39;PENDING&#39;, &#39;ANSWERED&#39;, &#39;CLOSED&#39;)</td><td>No</td><td>Ticket handling status</td></tr><tr><td><code>answer</code></td><td>TEXT</td><td>Yes</td><td>Administrator response text</td></tr><tr><td><code>parent_id</code></td><td>INT UNSIGNED</td><td>Yes</td><td>Parent ticket ID, used to identify child tickets</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Ticket creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last ticket update time</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="ticket-statuses" tabindex="-1"><code>$ticket_statuses</code> <a class="header-anchor" href="#ticket-statuses" aria-label="Permalink to “$ticket_statuses”">​</a></h3><p>Specifies the valid ticket statuses:</p><ul><li><code>PENDING</code>: Awaiting handling</li><li><code>ANSWERED</code>: Answered</li><li><code>CLOSED</code>: Closed</li></ul><p>The database default status is <code>PENDING</code>.</p><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h2><ul><li><code>customer()</code>: A <code>belongsTo</code> relationship with the <code>Customer</code> model; the customer who submitted the ticket.</li><li><code>user()</code>: A <code>belongsTo</code> relationship with the <code>User</code> model; the administrator or user associated with the response.</li><li><code>subTickets()</code>: A <code>hasMany</code> relationship with the <code>Ticket</code> model; child tickets, ordered by <code>id</code> in ascending order.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="evaluations" tabindex="-1"><code>evaluations()</code> <a class="header-anchor" href="#evaluations" aria-label="Permalink to “evaluations()”">​</a></h3><p>Returns the evaluations available for the ticket, including general evaluations, evaluations assigned to the <code>Ticket</code> model, and evaluations assigned to the current ticket.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li><code>customer_id</code> is required, and its foreign key references the <code>Customer</code> model. Deleting a customer also deletes the associated tickets (<code>ON DELETE CASCADE</code>).</li><li><code>user_id</code> is optional and references the <code>User</code> model. Deleting the associated user also deletes the associated tickets (<code>ON DELETE CASCADE</code>).</li><li>The <code>parent_id</code> field is used to create a parent-child structure. The table defines an index for this field, but no foreign key is defined.</li><li>Tickets can be evaluated and rated using the <code>Rate</code> rating system.</li><li>The <code>answer</code> field is intended to store the administrator&#39;s response, while <code>body</code> stores the original ticket message.</li><li>The <code>status</code> field is an <code>ENUM</code> type and accepts only <code>PENDING</code>, <code>ANSWERED</code>, and <code>CLOSED</code>.</li></ul>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};